using System;using System.Configuration;using System.Data;using System.Data.SqlClient;using System.IO;using System.Net;using System.Text;using System.Web.UI;using System.Web.UI.WebControls;namespace ZavaLoanPortal{public partial class Default:Page{protected void Page_Load(object sender,EventArgs e){if(!Request.IsAuthenticated){Response.Redirect("~/Login.aspx?ReturnUrl="+Server.UrlEncode(Request.RawUrl),false);Context.ApplicationInstance.CompleteRequest();return;}if(!IsPostBack){BindLoanProducts();BindLoanHistory();txtCustomerId.Text="1";txtTermMonths.Text="60";}}protected void wizLoanApplication_ActiveStepChanged(object sender,EventArgs e){if(wizLoanApplication.ActiveStepIndex==3){lblReviewSummary.Text="<b>Customer:</b> "+Server.HtmlEncode((txtFirstName.Text+" "+txtLastName.Text).Trim())+"<br/><b>Amount:</b> "+Server.HtmlEncode(txtRequestedAmount.Text)+"<br/><b>Term:</b> "+Server.HtmlEncode(txtTermMonths.Text)+" months";}}protected void wizLoanApplication_NextButtonClick(object sender,WizardNavigationEventArgs e){decimal amount;int term;if(wizLoanApplication.ActiveStepIndex==2&&(!decimal.TryParse(txtRequestedAmount.Text,out amount)||!int.TryParse(txtTermMonths.Text,out term))){e.Cancel=true;lblSubmissionStatus.Text="Enter valid loan amount and term.";}}protected void wizLoanApplication_FinishButtonClick(object sender,WizardNavigationEventArgs e){int customerId=int.Parse(txtCustomerId.Text);int productId=int.Parse(ddlLoanProduct.SelectedValue);decimal amount=decimal.Parse(txtRequestedAmount.Text);int term=int.Parse(txtTermMonths.Text);SubmitApi("<loanApplication><customerId>"+customerId+"</customerId><loanProductId>"+productId+"</loanProductId><requestedAmount>"+amount.ToString("F2")+"</requestedAmount><termMonths>"+term+"</termMonths></loanApplication>");using(var c=new SqlConnection(ConfigurationManager.ConnectionStrings["ZavaBankDb"].ConnectionString))using(var cmd=new SqlCommand("INSERT INTO LoanApplications (CustomerID,LoanProductID,RequestedAmount,TermMonths,Purpose,Status,ApplicationDate,AssignedOfficer,CreatedDate,ModifiedDate) VALUES (@c,@p,@a,@t,@u,'Submitted',GETDATE(),@o,GETDATE(),GETDATE());",c)){cmd.Parameters.AddWithValue("@c",customerId);cmd.Parameters.AddWithValue("@p",productId);cmd.Parameters.AddWithValue("@a",amount);cmd.Parameters.AddWithValue("@t",term);cmd.Parameters.AddWithValue("@u",(object)(txtPurpose.Text??""));cmd.Parameters.AddWithValue("@o",User.Identity.Name);c.Open();cmd.ExecuteNonQuery();}lblSubmissionStatus.Text="Application submitted.";BindLoanHistory();wizLoanApplication.ActiveStepIndex=0;}protected void gvLoanHistory_RowCommand(object sender,GridViewCommandEventArgs e){if(string.Equals(e.CommandName,"ReviewApplication",StringComparison.OrdinalIgnoreCase)){lblSubmissionStatus.Text="Application selected for review.";}}private void BindLoanProducts(){var t=new DataTable();using(var c=new SqlConnection(ConfigurationManager.ConnectionStrings["ZavaBankDb"].ConnectionString))using(var cmd=new SqlCommand("SELECT LoanProductID, ProductName FROM LoanProducts WHERE IsActive=1 ORDER BY ProductName;",c))using(var a=new SqlDataAdapter(cmd)){c.Open();a.Fill(t);}ddlLoanProduct.DataSource=t;ddlLoanProduct.DataTextField="ProductName";ddlLoanProduct.DataValueField="LoanProductID";ddlLoanProduct.DataBind();}private void BindLoanHistory(){var t=new DataTable();using(var c=new SqlConnection(ConfigurationManager.ConnectionStrings["ZavaBankDb"].ConnectionString))using(var cmd=new SqlCommand("SELECT TOP 25 ApplicationID, CustomerID, RequestedAmount, TermMonths, Status, ApplicationDate FROM LoanApplications ORDER BY ApplicationDate DESC;",c))using(var a=new SqlDataAdapter(cmd)){c.Open();a.Fill(t);}gvLoanHistory.DataSource=t;gvLoanHistory.DataBind();}private void SubmitApi(string payload){var url=ConfigurationManager.AppSettings["LoanOriginationApiUrl"]??"";if(url.Length==0)return;try{var r=(HttpWebRequest)WebRequest.Create(url);r.Method="POST";r.ContentType="application/xml";var b=Encoding.UTF8.GetBytes(payload);using(var s=r.GetRequestStream()){s.Write(b,0,b.Length);}using(var resp=(HttpWebResponse)r.GetResponse())using(var rd=new StreamReader(resp.GetResponseStream())){rd.ReadToEnd();}}catch{}}}}
